/** High-level local Design Intelligence recommender. Never writes. */
class Design_Core_Elementor_Design_Advisor{const MAX_BRIEF_BYTES=16384;private $catalog;public function __construct($catalog=null){$this->catalog=$catalog?:new Design_Core_Elementor_Design_Intelligence_Catalog();}public function recommend($brief,array $options=array()){$brief=trim((string)$brief);if(''===$brief)return new WP_Error('design_core_design_brief_required','A design brief is required.');if(strlen($brief)>self::MAX_BRIEF_BYTES)return new WP_Error('design_core_design_brief_too_large','The design brief exceeds the 16 KB Design Intelligence limit.');$match=$this->catalog->match_profile($brief,(string)($options['product_type']??''));if(is_wp_error($match))return $match;$d=$this->catalog->load();if(is_wp_error($d))return $d;$options['ux_rules']=$this->catalog->ux_rules(array(),max(1,min(50,(int)($options['max_rules']??24))));$profile=Design_Core_Elementor_Design_System_Profile::from_match($match,$brief,$options,(array)($d['source']??array()));$raw=(array)($match['profile']??array());$profile['content_strategy']=array('business_goals'=>array_values(array_map('sanitize_text_field',(array)($raw['business_goals']??array()))),'image_style'=>sanitize_text_field((string)($raw['image_style']??'')),'content_hierarchy'=>array_values(array_map('sanitize_text_field',(array)($raw['content_hierarchy']??array()))),'mobile_priority'=>array_values(array_map('sanitize_text_field',(array)($raw['mobile_priority']??array()))));try{Design_Core_Elementor_Design_System_Profile::validate($profile);}catch(Throwable $e){return new WP_Error('design_core_design_profile_invalid',$e->getMessage());}$warnings=array();if('low'===($profile['product']['confidence']??''))$warnings[]='Low-confidence product match; provide product_type before a real build.';$shell=$profile['page_strategy']['recommended_shell']??'';if($shell&&class_exists('Design_Core_Elementor_Page_Shell')&&!isset(Design_Core_Elementor_Page_Shell::definitions()[$shell]))$warnings[]='Recommended Page Shell is unavailable; resolve coverage before build.';return array('status'=>'success','profile'=>$profile,'catalog'=>$this->catalog->status(),'warnings'=>$warnings,'mutation'=>false);}public function enrich_ir(array $ir,array $profile){try{Design_Core_Elementor_Design_System_Profile::validate($profile);(new Design_Core_Elementor_Design_IR_Validator())->validate($ir);}catch(Throwable $e){return new WP_Error('design_core_design_ir_enrichment_invalid',$e->getMessage());}$svc=new Design_Core_Elementor_Design_Token_Service();$p=$svc->normalize((array)($profile['tokens']??array()));$e=$svc->normalize((array)($ir['tokens']??array()));$ir['tokens']=array('schema_version'=>Design_Core_Elementor_Design_Token_Service::SCHEMA_VERSION,'colors'=>array_replace((array)($p['colors']??array()),(array)($e['colors']??array())),'typography'=>array_replace_recursive((array)($p['typography']??array()),(array)($e['typography']??array())),'spacing'=>array_replace((array)($p['spacing']??array()),(array)($e['spacing']??array())),'radius'=>array_replace((array)($p['radius']??array()),(array)($e['radius']??array())));$ir['diagnostics']=is_array($ir['diagnostics']??null)?$ir['diagnostics']:array();$ir['diagnostics']['design_intelligence']=array('schema_version'=>Design_Core_Elementor_Design_System_Profile::SCHEMA_VERSION,'provider'=>'design-core-rc22','product_id'=>sanitize_key((string)($profile['product']['id']??'')),'recommended_shell'=>sanitize_key((string)($profile['page_strategy']['recommended_shell']??'')),'content_strategy'=>(array)($profile['content_strategy']??array()));return $ir;}public function recommend_and_enrich(array $ir,$brief,array $options=array()){$r=$this->recommend($brief,$options);if(is_wp_error($r))return $r;$x=$this->enrich_ir($ir,$r['profile']);return is_wp_error($x)?$x:array('recommendation'=>$r,'design_ir'=>$x);}}
